  if (select count(*) from public.app_affaire_ledger where coalesce(date_annulation_app, '') <> '') <> 472 + 229 then
    raise exception '⛔ controle : le nombre de dates d''annulation n''est pas 472 + 229'; end if;
  e := (select md5(coalesce(string_agg(concat_ws('|', app_affaire_id, kind, state, app_chaine_id, app_dossier_numero, coalesce(date_annulation_app, '-'), coalesce(motif_annulation_app, '-'), coalesce(vente_reglee_app, '-'), coalesce(numero_facture_app, '-'), coalesce(honoraires_entree_app::text, '-')), ';' order by app_affaire_id), '')) from public.app_affaire_ledger where app_affaire_id in (28148, 20296, 20293, 14812, 14941, 19009, 17205, 3631, 7598, 23335, 7185, 20, 6341, 6138, 8868, 23025, 4192, 14810, 8917, 14964, 4255, 16169, 14922, 1061, 6379, 2499, 27052, 16017, 20268, 9359, 19102, 8911, 8925, 6450, 10027, 14085, 25867, 24337, 26016, 27140, 14961, 24094, 19132, 27170, 27185, 27526, 2490, 7250, 21884, 16018, 14962, 4321, 21963, 16045, 25880, 161, 11523, 27247, 24121, 15002, 15020, 14819, 14816, 10018, 17291, 178, 4293, 19512, 24165, 24168, 7273, 17024, 15072, 15042, 15073, 17366, 16249, 15005, 11596, 15915, 4421, 16051, 9447, 27528, 11524, 15032, 27280, 4389, 4358, 4353, 25742, 23037, 1089, 4387, 1589, 24610, 27404, 9300, 24454, 19112, 4633, 6203, 27372, 16861, 19472, 22024, 27461, 19473, 24336, 4544, 20405, 19466, 11561, 26106, 20089, 9898, 1000126, 15051, 16858, 7761, 25752, 4623, 11365, 27427, 4463, 23486, 19130, 11447, 24311, 4472, 24335, 1105, 4498, 1104, 17431, 14143, 7907, 17401, 6208, 17410, 4130, 16185, 27533, 27449, 17411, 27470, 22216, 11411, 15925, 19750, 19785, 19746, 4134, 24542, 14114, 6557, 27513, 24401, 4923, 4578, 22209, 6215, 4799, 26043, 25753, 20513, 4587, 4790, 24652, 24589, 16134, 16383, 17642, 11767, 15103, 11193, 19142, 4654, 16393, 26831, 1203, 27610, 27556, 27560, 4668, 4719, 23500, 22210, 24478, 6204, 24573, 19830, 11188, 27687, 26852, 6603, 17521, 11885, 11963, 11972, 14823, 19049, 989, 28787, 28687, 28633, 23888, 28584, 28839, 28631, 28731, 28725, 28733, 28340, 28728, 11139, 14824, 28736, 28555, 27196, 28956, 28974, 28975, 28996, 29000, 29025, 30648, 30806, 30816));
